// Some portions generated by Codex

// @ts-check
const fs = require('fs');
const path = require('path');

const { test, expect } = require('@playwright/test');

const playwrightLibraryDirectory = path.join(path.dirname(require.resolve('playwright-core')), 'lib');
const { PNG } = require(path.join(playwrightLibraryDirectory, 'utilsBundle'));
const pixelmatch = require(path.join(playwrightLibraryDirectory, 'third_party/pixelmatch'));

const SERVER_BASE_URL = process.env.RDF4J_SERVER_BASE_URL || 'http://127.0.0.1:8080/rdf4j-server';
const WORKBENCH_BASE_URL = process.env.RDF4J_WORKBENCH_BASE_URL || 'http://127.0.0.1:8080/rdf4j-workbench';
const REFERENCE_PATH = process.env.QUERY_EXPLANATION_REFERENCE;
const ACTUAL_PATH = process.env.QUERY_EXPLANATION_ACTUAL || '/tmp/rdf4j-query-explanation-actual.png';
const DIFF_PATH = process.env.QUERY_EXPLANATION_DIFF || '/tmp/rdf4j-query-explanation-diff.png';
const REPOSITORY_ID = 'query-explanation-visual';
const ORIGINAL_QUERY = `SELECT DISTINCT ?a WHERE {
  ?a a <http://example#Type> .
  ?a <http://example#id> ?b .
  ?a <http://example#temp> ?c .
}`;

test.use({
    viewport: { width: 1050, height: 900 },
    deviceScaleFactor: 2
});

test('original query explanation matches the visual reference pixel-for-pixel', async ({ page, request }, testInfo) => {
    test.skip(testInfo.project.name !== 'chromium', 'The supplied reference was captured in Chromium');
    test.skip(!REFERENCE_PATH, 'Set QUERY_EXPLANATION_REFERENCE to run the opt-in pixel comparison');

    const consoleErrors = [];
    page.on('console', message => {
        if (message.type() === 'error') {
            consoleErrors.push(message.text());
        }
    });

    await request.delete(`${SERVER_BASE_URL}/repositories/${REPOSITORY_ID}`);
    const createResponse = await request.put(`${SERVER_BASE_URL}/repositories/${REPOSITORY_ID}`, {
        headers: { 'Content-Type': 'text/turtle' },
        data: nativeRepositoryConfig(REPOSITORY_ID)
    });
    expect([200, 201, 204]).toContain(createResponse.status());
    const namespaceResponse = await request.put(
        `${SERVER_BASE_URL}/repositories/${REPOSITORY_ID}/namespaces/rdf`,
        {
            headers: { 'Content-Type': 'text/plain' },
            data: 'http://www.w3.org/1999/02/22-rdf-syntax-ns#'
        }
    );
    expect([200, 201, 204]).toContain(namespaceResponse.status());

    await page.goto(`${WORKBENCH_BASE_URL}/repositories/${REPOSITORY_ID}/query`);
    await expect(page).toHaveTitle(/RDF4J Workbench/);
    await page.locator('.CodeMirror').waitFor();
    await page.evaluate(query => {
        document.getElementsByClassName('CodeMirror')[0].CodeMirror.setValue(query);
    }, ORIGINAL_QUERY);
    await page.locator('#explain-trigger').click();
    await page.locator('#query-explanation .query-explanation-token--node-type').first().waitFor();
    await page.evaluate(async () => document.fonts.ready);
    await expect(page.locator('#query-explanation')).toContainText('Distinct');
    await expect(page.locator('.query-explanation-overlay--visible')).toHaveCount(0);
    expect(consoleErrors).toEqual([]);

    const clip = await page.locator('#query-explanation-row .query-explanation-surface').evaluate(element => {
        const bounds = element.getBoundingClientRect();
        return {
            x: Math.round((bounds.left - 17.5) * 2) / 2,
            y: Math.round((bounds.top - 33.5) * 2) / 2,
            width: 830,
            height: 354
        };
    });
    await page.mouse.move(0, 0);
    await page.screenshot({ path: ACTUAL_PATH, clip, animations: 'disabled', caret: 'hide' });

    const surface = page.locator('#query-explanation-row .query-explanation-surface');
    const copyButton = page.locator('#copy-explanation');
    expect(await copyButton.evaluate(element => getComputedStyle(element).opacity)).toBe('0');
    await surface.hover();
    await expect.poll(() => copyButton.evaluate(element => getComputedStyle(element).opacity)).toBe('1');

    const reference = PNG.sync.read(fs.readFileSync(REFERENCE_PATH));
    const actual = PNG.sync.read(fs.readFileSync(ACTUAL_PATH));
    expect({ width: actual.width, height: actual.height }).toEqual({ width: 1660, height: 708 });
    expect({ width: actual.width, height: actual.height }).toEqual({
        width: reference.width,
        height: reference.height
    });

    const diff = new PNG({ width: actual.width, height: actual.height });
    const differentPixels = pixelmatch(reference.data, actual.data, diff.data, actual.width, actual.height, {
        includeAA: true,
        threshold: 0
    });
    fs.writeFileSync(DIFF_PATH, PNG.sync.write(diff));

    expect(differentPixels, `Pixel mismatch; inspect ${ACTUAL_PATH} and ${DIFF_PATH}`).toBe(0);
});

function nativeRepositoryConfig(repositoryId) {
    return `@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#>.
@prefix config: <tag:rdf4j.org,2023:config/>.

[] a config:Repository ;
   config:rep.id "${repositoryId}" ;
   rdfs:label "Query explanation visual test" ;
   config:rep.impl [
      config:rep.type "openrdf:SailRepository" ;
      config:sail.impl [
         config:sail.type "openrdf:NativeStore"
      ]
   ].
`;
}
